function area(parent,label,id,value){const l=el('label',label),n=el('textarea');l.htmlFor=id;n.id=id;n.rows=16;n.style.width='100%';n.style.minWidth='0';n.value=value;parent.append(l,n);return n;}
function advancedEditor(updateLocation=true){const editor=serviceEditor;if(!editor)return;editor.mode='advanced';if(updateLocation)serviceEditorLocation(editor.step,'advanced');const f=form(editor.isNew?'Add service':editor.service.name||editor.id);f.remove();editorHeader('advanced');f.className='service-form';content.append(f);f.append(el('h2','Edit configuration JSON'),el('p','Entire service configuration. Exact imported fields are preserved. Credential values use separate write-only actions.'));const n=area(f,'Service configuration JSON','advanced-json',editor.advancedText??JSON.stringify(editor.service,null,2));n.oninput=()=>{editor.advancedText=n.value;editorDirty=true;document.getElementById('service-edit-state').textContent='Unsaved changes';};button(f,'Return to guided forms');f.onsubmit=e=>{e.preventDefault();if(acceptAdvanced())renderEditor(editor.step);};action(f,'Save draft',async()=>{try{await saveEditor();document.getElementById('service-edit-state').textContent='Saved draft · not in use';banner.textContent='';}catch(e){serviceError(e);}});action(f,'Back to Services',()=>leaveEditor(()=>services()));}
window.addEventListener('popstate',e=>{if(!serviceEditor)return;e.stopImmediatePropagation();const q=new URLSearchParams(location.search);if(q.has('edit')&&(q.get('service')===serviceEditor.id||q.get('service')==='new')){if(serviceEditor.mode==='advanced'&&!acceptAdvanced()){serviceEditorLocation(serviceEditor.step,'advanced',true);return;}const step=Number(q.get('edit'));if(!Number.isInteger(step)||step<0||step>5){showError('Unknown configuration section.');return;}q.get('mode')==='advanced'?advancedEditor(false):renderEditor(step,false);}else{const target=location.href;serviceEditorLocation(serviceEditor.step,serviceEditor.mode,true);leaveEditor(()=>{history.replaceState(null,'',target);services();});}});
function editRule(rule){const f=form('Edit request policy rule');editField(f,'Rule identifier','edit-rule-id',rule.id,v=>rule.id=v,true);choice(f,'Effect','edit-rule-effect',[['allow','Allow'],['deny','Deny']],rule.effect,v=>rule.effect=v);editField(f,'Priority (highest first)','edit-rule-priority',rule.priority,v=>rule.priority=Number(v),true,'number');const changed=()=>editorDirty=true;for(const [key,label] of [['methods','Method'],['hosts','Host regex source'],['paths','Path regex source']]){rule[key]??=[];rowList(f,label,'edit-rule-'+key,rule[key],changed);}f.append(el('p','Regex sources are literal and preserved exactly. For exact or prefix paths use the basic rule builder. Higher numeric priority runs first; deny wins ties, otherwise source order is preserved.'));editField(f,'Reason','edit-rule-reason',rule.reason,v=>rule.reason=v);choice(f,'Response scanning','edit-rule-scan',[['inherit','Use shared scanning'],['disabled','Disable all Secretlint rules'],['exceptions','Disable selected rules']],rule.secretlint?.enabled===false?'disabled':rule.secretlint?.disabled_rules?'exceptions':'inherit',v=>{if(v==='inherit')delete rule.secretlint;else rule.secretlint=v==='disabled'?{enabled:false}:{disabled_rules:[]};editorDirty=true;editRule(rule);});if(rule.secretlint?.disabled_rules)for(const id of supportedScannerRules)check(f,'Disable '+id.replace('@secretlint/secretlint-rule-',''),'disable-'+supportedScannerRules.indexOf(id),rule.secretlint.disabled_rules.includes(id),v=>{rule.secretlint.disabled_rules=v?[...rule.secretlint.disabled_rules,id]:rule.secretlint.disabled_rules.filter(x=>x!==id);});choice(f,'Binary response settings','edit-rule-binary-mode',[['inherit','Use default binary protection'],['override','Override for this rule']],rule.binary_response?'override':'inherit',v=>{if(v==='inherit')delete rule.binary_response;else rule.binary_response={scan:true,max_size:'100kb'};editorDirty=true;editRule(rule);});if(rule.binary_response){check(f,'Scan binary responses','edit-rule-binary-scan',rule.binary_response.scan??true,v=>rule.binary_response.scan=v);editField(f,'Maximum binary scan size (e.g. 100kb or unlimited)','edit-rule-binary-size',rule.binary_response.max_size??'100kb',v=>rule.binary_response.max_size=v,true);f.append(el('p','Disabling scanning or using unlimited changes the guard for this rule and requires review acknowledgment.'));}button(f,'Keep rule changes');f.onsubmit=e=>{e.preventDefault();if(validateFields(f)){editorDirty=true;renderEditor(3);}};}
async function policyTester(id){try{const listing=await api('services');const f=form('Safe policy tester');f.append(el('p','No downstream request is sent. Preview is not an execution grant.'));choice(f,'Identity','preview-identity',listing.eligible.map(u=>[u.id,u.email]),listing.eligible[0]?.id??'',()=>{});choice(f,'Configuration source','preview-source',[['applied','Applied configuration'],['draft','Saved draft']],'applied',()=>{});editField(f,'Destination identifier (optional for one destination)','preview-destination','',()=>{});editField(f,'Method','preview-method','GET',()=>{},true);editField(f,'Canonical path or absolute URL','preview-target','/',()=>{},true);button(f,'Explain policy');const result=el('div');result.setAttribute('role','status');content.append(result);f.onsubmit=async e=>{e.preventDefault();try{const target=f.querySelector('#preview-target').value,destination=f.querySelector('#preview-destination').value;const r=await api('service/preview',{id,identity:f.querySelector('#preview-identity').value,source:f.querySelector('#preview-source').value,method:f.querySelector('#preview-method').value,...(destination?{destination}:{}),...(target.startsWith('/')?{path:target}:{url:target})});result.replaceChildren(el('p',r.allowed?'Allowed':'Denied'),el('p',r.reason),el('p','Canonical target: '+r.canonicalTarget),el('p','Winning rule: '+(r.matchedRule??'default')),el('p','Effective protection: TLS '+(r.protection.tls?'verified':'verification disabled')+'; '+r.protection.secretlint.rules.length+' Secretlint rules; '+r.protection.sensitiveNames.patterns.length+' sensitive-name patterns; binary scanning '+(r.protection.binaryResponse.scan?'enabled':'disabled')),fullDetails('Effective secret detection details',r.protection));}catch(e){serviceError(e);}};action(f,'Return to Services',()=>leaveEditor(()=>services()));}catch(e){serviceError(e);}}
